  async function syncCurrentBaiBaiRuntimeAndUI(
    pm,
    presetName,
    state,
    assignments,
    renames,
    promptNames = new Map(),
    unassignments = []
  ) {
    const extensionStates = getAccessibleBaiBaiExtensionStates();
    const currentNames = getCurrentBaiBaiPresetNames(pm, extensionStates);
    if (!currentNames.has(String(presetName))) {
      return { current: false, runtime: false, memory: false, ui: false, rendered: false };
    }

    if (!extensionStates.length) {
      return { current: true, runtime: false, memory: false, ui: false, rendered: false };
    }

    const snapshot = clone(state);
    const syncKey = `${presetName}:${JSON.stringify(snapshot)}`;
    let runtime = false;
    let memory = false;
    let ui = false;
    let rendered = false;
    const renderedPromptManagers = new Set();

    for (const extensionState of extensionStates) {
      if (!isPresetStillSelected(pm, presetName)) {
        return { current: false, runtime, memory, ui, rendered, stale: true };
      }
      extensionState.presetPromptGroupRuntimePresetName = presetName;
      extensionState.presetPromptGroupRuntimeState = clone(snapshot);
      extensionState.presetPromptGroupExtensionSyncKey = syncKey;
      runtime = true;

      let manager = extensionState[VUE_MANAGER_KEY];
      updatePendingBaiBaiSnapshots(manager, presetName, snapshot, syncKey);

      if (manager && typeof manager === 'object') {
        manager.lastSyncSignature = '';
        manager.lastStructureSignature = '';
      }

      const renderPatch = extensionState[VUE_RENDER_PATCH_KEY];
      const promptManager = renderPatch?.manager;
      memory = writeBaiBaiLivePresetMemory(promptManager, snapshot) || memory;
      memory = writeBaiBaiLivePromptNames(promptManager, promptNames) || memory;

      try {
        if (
          isPresetStillSelected(pm, presetName)
          && typeof promptManager?.renderPromptManagerListItems === 'function'
          && !renderedPromptManagers.has(promptManager)
        ) {
          renderedPromptManagers.add(promptManager);
          await promptManager.renderPromptManagerListItems();
          rendered = true;
        }
      } catch (error) {
        console.warn('[预设工坊×柏宝箱] 调用柏宝箱列表重建失败，改用直接模型同步', error);
      }

      if (!isPresetStillSelected(pm, presetName)) continue;

      /* render 期间柏宝箱可能才创建 Vue manager，所以必须重新取一次。 */
      manager = extensionState[VUE_MANAGER_KEY] || manager;
      updatePendingBaiBaiSnapshots(manager, presetName, snapshot, syncKey);

      if (manager && typeof manager === 'object') {
        manager.lastSyncSignature = '';
        manager.lastStructureSignature = '';
      }

      if (
        !vueModelHasAssignments(manager, assignments)
        || !vueModelHasUnassignments(manager, unassignments)
      ) {
        patchVueModelDirectly(manager, assignments, unassignments);
      }
      if (!vueModelHasRenames(manager, renames)) {
        patchVueGroupNamesDirectly(manager, renames);
      }
      if (!vueModelHasPromptNames(manager, promptNames)) {
        patchVuePromptNamesDirectly(manager, promptNames);
      }

      if (manager?.state && typeof manager.state === 'object') {
        manager.state.renderKey = Number(manager.state.renderKey || 0) + 1;
      }

      try { await manager?.vue?.nextTick?.(); } catch (_) {}
      ui = (
        vueModelHasAssignments(manager, assignments)
        && vueModelHasUnassignments(manager, unassignments)
        && vueModelHasRenames(manager, renames)
        && vueModelHasPromptNames(manager, promptNames)
      ) || ui;
    }

    return { current: true, runtime, memory, ui, rendered };
  }


  function persistedAssignmentsMatch(persisted, assignments) {
    if (!persisted?.prompts || typeof persisted.prompts !== 'object') return false;
    const persistedGroupIds = new Set(
      (Array.isArray(persisted.groups) ? persisted.groups : [])
        .map(group => String(group?.id || ''))
        .filter(Boolean)
    );
    return assignments.every(assignment =>
      persistedGroupIds.has(String(assignment.groupId || ''))
      && assignment.newIds.every(promptId =>
        String(persisted.prompts?.[promptId]?.groupId || '') === assignment.groupId
      )
    );
  }

  function persistedUnassignmentsMatch(persisted, unassignments) {
    if (!persisted?.prompts || typeof persisted.prompts !== 'object') {
      return unassignments.length === 0;
    }
    return unassignments.every(unassignment =>
      unassignment.newIds.every(promptId =>
        !String(persisted.prompts?.[promptId]?.groupId || '')
      )
    );
  }

  function persistedRenamesMatch(persisted, renames) {
    if (!Array.isArray(persisted?.groups)) return false;
    return renames.every(rename => {
      const group = persisted.groups.find(
        item => String(item?.id || '') === rename.groupId
      );
      return Boolean(group) && String(group.name || '') === rename.newName;
    });
  }

  async function verifyPersistedChanges(pm, presetName, assignments, renames, unassignments = []) {
    const retryDelays = [0, 40, 100, 220];
    for (const delay of retryDelays) {
      if (delay) await new Promise(resolve => setTimeout(resolve, delay));
      const persisted = readState(pm, presetName);
      if (
        persistedAssignmentsMatch(persisted, assignments)
        && persistedUnassignmentsMatch(persisted, unassignments)
        && persistedRenamesMatch(persisted, renames)
      ) return true;
    }
    return false;
  }

  async function flushPreset(presetName) {
    const name = String(presetName || '');
    if (!name) return false;

    const intents = queues.get(name) || [];
    const renameIntents = Array.from(renameQueues.get(name)?.values?.() || []);
    const promptSnapshot = promptSnapshotQueues.get(name);
    const promptNames = promptSnapshot?.names instanceof Map
      ? promptSnapshot.names
      : readCurrentPromptNames(name);
    if (!intents.length && !renameIntents.length && !promptNames.size) return false;
    queues.delete(name);
    renameQueues.delete(name);
    promptSnapshotQueues.delete(name);

    const pm = getPresetManager();
    if (
      !pm
      || typeof pm.readPresetExtensionField !== 'function'
      || typeof pm.writePresetExtensionField !== 'function'
    ) {
      console.warn('[预设工坊×柏宝箱] 当前酒馆没有可用的 OpenAI PresetManager 扩展字段 API');
      toastr.warning('预设已保存，但无法连接分组接口');
      return false;
    }

    const state = readState(pm, name) || { version: 1, groups: [], prompts: {} };
    if (!Array.isArray(state.groups)) state.groups = [];
    if (!state.prompts || typeof state.prompts !== 'object') state.prompts = {};

    state.version = Number(state.version) || 1;
    state.groups = state.groups.map(group => ({ ...group }));
    state.prompts = { ...state.prompts };

    let changed = 0;
    const syncedGroups = new Set();
    const assignments = [];
    const unassignments = [];
    const renamedGroups = [];
    const createdGroups = [];

    for (const rename of renameIntents) {
      const group = state.groups.find(
        item => String(item?.id || '') === rename.groupId
      );
      if (!group) {
        console.warn('[预设工坊×柏宝箱] 找不到要改名的柏宝箱分组：', rename);
        continue;
      }

      const oldName = String(group.name || '');
      if (oldName !== rename.newName) {
        group.name = rename.newName;
        changed += 1;
      }
      renamedGroups.push({
        groupId: rename.groupId,
        oldName,
        newName: rename.newName,
      });
      syncedGroups.add(rename.newName);
    }

    for (const intent of intents) {
      if (intent.unassign === true) {
        const unassignedIds = [];
        for (const newId of intent.newIds) {
          const currentPromptState = state.prompts[newId];
          if (currentPromptState && typeof currentPromptState === 'object') {
            const nextPromptState = { ...currentPromptState };
            if (String(nextPromptState.groupId || '')) {
              delete nextPromptState.groupId;
              if (Object.keys(nextPromptState).length) state.prompts[newId] = nextPromptState;
              else delete state.prompts[newId];
              changed += 1;
            }
          }
          unassignedIds.push(newId);
        }
        if (unassignedIds.length) {
          unassignments.push({
            targetId: intent.targetId,
            targetPosition: intent.targetPosition,
            newIds: unassignedIds,
          });
        }
        continue;
      }

      let groupId = '';
      if (intent.createGroup === true) {
        const created = createBaiBaiGroup(state, intent);
        groupId = created.groupId;
        createdGroups.push(created);
        changed += 1;
      } else {
        groupId = findGroupId(state, intent);
      }
      if (!groupId) {
        console.warn('[预设工坊×柏宝箱] 找不到目标柏宝箱分组：', intent);
        continue;
      }

      const group = state.groups.find(item => String(item?.id || '') === groupId);
      if (group?.name) syncedGroups.add(String(group.name));

      const assignedIds = [];
      for (const newId of intent.newIds) {
        if (String(state.prompts[newId]?.groupId || '') !== groupId) {
          state.prompts[newId] = { groupId };
          changed += 1;
        }
        assignedIds.push(newId);
      }

      if (assignedIds.length) {
        assignments.push({
          groupId,
          targetId: intent.targetId,
          targetPosition: intent.targetPosition,
          newIds: assignedIds,
        });
      }
    }

    if (
      !assignments.length
      && !unassignments.length
      && !renamedGroups.length
      && !createdGroups.length
      && !promptNames.size
    ) {
      toastr.warning('预设已保存，但没有识别到要同步的分组修改');
      return false;
    }

    const hasGroupChanges = Boolean(
      assignments.length
      || unassignments.length
      || renamedGroups.length
      || createdGroups.length
    );
    if (hasGroupChanges) {
      try {
        await pm.writePresetExtensionField({
          name,
          path: PATH,
          value: clone(state),
        });
      } catch (error) {
        console.error('[预设工坊×柏宝箱] 柏宝箱分组写入失败', error);
        toastr.warning('预设已保存，但柏宝箱分组写入失败，请查看控制台');
        return false;
      }
    }

    let runtime = { current: false, runtime: false, memory: false, ui: false, rendered: false };
    try {
      runtime = await syncCurrentBaiBaiRuntimeAndUI(
        pm,
        name,
        state,
        assignments,
        renamedGroups,
        promptNames,
        unassignments
      );
    } catch (error) {
      console.warn('[预设工坊×柏宝箱] 分组已写入，但当前列表即时刷新失败', error);
    }

    let persisted = !hasGroupChanges;
    if (hasGroupChanges) try {
      persisted = await verifyPersistedChanges(pm, name, assignments, renamedGroups, unassignments);
    } catch (error) {
      console.warn('[预设工坊×柏宝箱] 写入后复查未完成，不作为保存失败处理', error);
    }
    if (hasGroupChanges && !persisted) {
      console.warn('[预设工坊×柏宝箱] 写入接口已完成，但即时复查仍为旧缓存；不作为保存失败处理');
    }

    const groups = [...syncedGroups];
    const suffix = groups.length ? ` → ${groups.join(' / ')}` : '';
    const assignedTotal = new Set(assignments.flatMap(item => item.newIds)).size;
    const unassignedTotal = new Set(unassignments.flatMap(item => item.newIds)).size;
    const total = new Set([
      ...assignments.flatMap(item => item.newIds),
      ...unassignments.flatMap(item => item.newIds),
    ]).size;
    const renameCount = renamedGroups.length;
    const resultLabel = assignedTotal && unassignedTotal
      ? `分组已同步 ${assignedTotal} 条，并移出分组 ${unassignedTotal} 条${suffix}`
      : unassignedTotal
        ? `已移出分组 ${unassignedTotal} 条`
        : total && renameCount
          ? `分组已同步 ${total} 条并改名 ${renameCount} 个${suffix}`
          : total
            ? `分组已同步 ${total} 条${suffix}`
        : `分组名称已同步 ${renameCount} 个${suffix}`;

    const suppressSuccessMessage = API.__suppressNextSuccessMessage === true;
    const compactMessage = String(API.__nextSuccessMessage || '').trim();
    if (suppressSuccessMessage) delete API.__suppressNextSuccessMessage;
    if (!hasGroupChanges) {
      /* 普通保存已有自己的成功提示；这里只负责让柏宝箱当前分组成员即时改名。 */
      if (compactMessage) delete API.__nextSuccessMessage;
    } else if (suppressSuccessMessage) {
      if (compactMessage) delete API.__nextSuccessMessage;
    } else if (compactMessage) {
      delete API.__nextSuccessMessage;
      toastr.success(compactMessage);
    } else if (runtime.current && runtime.runtime && runtime.ui) {
      toastr.success(resultLabel);
    } else if (runtime.current && runtime.runtime) {
      toastr.info(`${resultLabel}，重新打开预设列表即可显示`);
    } else {
      toastr.success(resultLabel);
    }

    console.info(`[预设工坊×柏宝箱] V${GROUP_SYNC_VERSION} 分组成员、名称与整组同步完成：`, {
      presetName: name,
      changed,
      total,
      assignedTotal,
      unassignedTotal,
      unassignments,
      renamedGroups,
      createdGroups,
      groups,
      promptNameCount: promptNames.size,
      persisted,
      runtime,
    });
    return true;
  }

  function clearPreset(presetName) {
    const name = String(presetName || '');
    queues.delete(name);
    renameQueues.delete(name);
    promptSnapshotQueues.delete(name);
  }

  const FLAT_DROP_CANCEL = '__pmm_flat_drop_cancel__';
  const FLAT_DROP_UNGROUPED = '__pmm_flat_drop_ungrouped__';
  let activeFlatDropChooserCancel = null;

  function applyQueuedMembershipsToState(state, presetName) {
    if (!state || !Array.isArray(state.groups) || !state.prompts) return state;
    for (const intent of queues.get(String(presetName || '')) || []) {
      if (intent.unassign === true) {
        for (const promptId of intent.newIds) delete state.prompts[promptId];
        continue;
      }

      let groupId = '';
      if (intent.createGroup === true && intent.createdGroupId) {
        groupId = String(intent.createdGroupId);
        if (!state.groups.some(group => String(group?.id || '') === groupId)) {
          state.groups.push({
            id: groupId,
            name: String(intent.targetGroupTitle || '').trim() || '新分组',
            collapsed: false,
          });
        }
      } else {
        groupId = findGroupId(state, intent);
      }
      if (!groupId) continue;
      for (const promptId of intent.newIds) state.prompts[promptId] = { groupId };
    }
    return state;
  }

  function resolveFlatDropSection(intent) {
    const presetName = String(intent?.presetName || '');
    const targetId = String(intent?.targetId || '');
    const orderedIds = Array.isArray(intent?.orderedIds)
      ? intent.orderedIds.map(String).filter(Boolean)
      : [];
    if (!presetName || !targetId || !orderedIds.length) {
      return { sectionId: '', ambiguous: false };
    }

    const targetIndex = orderedIds.indexOf(targetId);
    if (targetIndex < 0) return { sectionId: '', ambiguous: false };
    const insertionIndex = targetIndex + (intent?.targetPosition === 'before' ? 0 : 1);
    const previousId = insertionIndex > 0 ? orderedIds[insertionIndex - 1] : '';
    const nextId = insertionIndex < orderedIds.length ? orderedIds[insertionIndex] : '';

    const pm = getPresetManager();
    const state = applyQueuedMembershipsToState(readState(pm, presetName), presetName);
    if (!state?.prompts || !Array.isArray(state?.groups)) {
      return { sectionId: '', ambiguous: false };
    }

    const groups = new Map(
      state.groups
        .map(group => [String(group?.id || ''), String(group?.name || group?.title || '未命名分组')])
        .filter(([groupId]) => Boolean(groupId))
    );
    const groupOf = promptId => {
      const groupId = String(state.prompts?.[promptId]?.groupId || '');
      return groups.has(groupId) ? groupId : '';
    };
    const previousGroupId = groupOf(previousId);
    const nextGroupId = groupOf(nextId);

    if (previousGroupId && nextGroupId && previousGroupId === nextGroupId) {
      return { sectionId: `baibai_${previousGroupId}`, ambiguous: false };
    }
    if (previousGroupId && nextGroupId && previousGroupId !== nextGroupId) {
      return {
        sectionId: '',
        ambiguous: true,
        previous: {
          sectionId: `baibai_${previousGroupId}`,
          name: groups.get(previousGroupId),
        },
        next: {
          sectionId: `baibai_${nextGroupId}`,
          name: groups.get(nextGroupId),
        },
      };
    }

    /* 列表最前或最后只有一个相邻分组时，可明确继承；分组与未分组交界保持未分组。 */
    if (!previousId && nextGroupId) {
      return { sectionId: `baibai_${nextGroupId}`, ambiguous: false };
    }
    if (!nextId && previousGroupId) {
      return { sectionId: `baibai_${previousGroupId}`, ambiguous: false };
    }
    return { sectionId: '', ambiguous: false };
  }

  function showFlatDropGroupChooser(resolution, preserveGroupTitle = '') {
    try { activeFlatDropChooserCancel?.(); } catch (_) {}

    return new Promise(resolve => {
      let doc = null;
      try { doc = ROOT?.document || window.top?.document || document; } catch (_) { doc = document; }
      if (!doc?.body) {
        resolve('');
        return;
      }

      const overlay = doc.createElement('div');
      overlay.id = 'pmm-flat-drop-group-chooser';
      overlay.style.cssText = 'position:fixed;inset:0;z-index:2147483645;display:flex;align-items:center;justify-content:center;padding:18px;background:rgba(0,0,0,.52);backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px);';

      const card = doc.createElement('div');
      card.style.cssText = 'box-sizing:border-box;width:min(420px,calc(100vw - 36px));padding:18px;border:1px solid rgba(255,255,255,.16);border-radius:14px;background:var(--SmartThemeBlurTintColor,#1f2635);color:var(--SmartThemeBodyColor,#f4f6fb);box-shadow:0 18px 55px rgba(0,0,0,.42);font:14px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;';

      const title = doc.createElement('div');
      title.textContent = '请选择条目要进入的分组';
      title.style.cssText = 'font-size:16px;font-weight:750;margin-bottom:6px;';

      const hint = doc.createElement('div');
      hint.textContent = '当前落点位于两个分组的交界处，工坊无法自动判断。';
      hint.style.cssText = 'opacity:.72;margin-bottom:14px;';

      const actions = doc.createElement('div');
      actions.style.cssText = 'display:flex;flex-direction:column;gap:9px;';

      let finished = false;
      const finish = sectionId => {
        if (finished) return;
        finished = true;
        try { doc.removeEventListener('keydown', onKeyDown, true); } catch (_) {}
        try { overlay.remove(); } catch (_) {}
        activeFlatDropChooserCancel = null;
        resolve(String(sectionId || ''));
      };
      const onKeyDown = event => {
        if (event.key === 'Escape') {
          event.preventDefault();
          finish(FLAT_DROP_CANCEL);
        }
      };
      const addButton = (label, sectionId, primary = false) => {
        const button = doc.createElement('button');
        button.type = 'button';
        button.textContent = label;
        button.style.cssText = `box-sizing:border-box;width:100%;min-height:42px;padding:9px 12px;border-radius:9px;border:1px solid ${primary ? 'rgba(96,165,250,.8)' : 'rgba(255,255,255,.15)'};background:${primary ? 'rgba(59,130,246,.24)' : 'rgba(255,255,255,.06)'};color:inherit;text-align:left;font:inherit;cursor:pointer;`;
        button.addEventListener('click', () => finish(sectionId));
        actions.appendChild(button);
      };

      addButton(`加入「${resolution.previous.name}」`, resolution.previous.sectionId, true);
      addButton(`加入「${resolution.next.name}」`, resolution.next.sectionId, true);
      addButton(
        preserveGroupTitle ? `保留为独立分组「${preserveGroupTitle}」` : '保持未分组',
        FLAT_DROP_UNGROUPED,
        false
      );
      card.append(title, hint, actions);
      overlay.appendChild(card);
      doc.body.appendChild(overlay);
      doc.addEventListener('keydown', onKeyDown, true);
      activeFlatDropChooserCancel = () => finish(FLAT_DROP_CANCEL);
    });
  }

  async function chooseFlatDropSection(intent) {
    const resolution = resolveFlatDropSection(intent);
    if (!resolution.ambiguous) return resolution.sectionId || '';
    const choice = await showFlatDropGroupChooser(
      resolution,
      String(intent?.preserveGroupTitle || '')
    );
    return choice.startsWith('baibai_') ? choice : '';
  }

  async function chooseFlatMoveAssignment(intent) {
    const resolution = resolveFlatDropSection(intent);
    if (!resolution.ambiguous) {
      const sectionId = String(resolution.sectionId || '');
      return {
        cancelled: false,
        sectionId,
        unassign: !sectionId,
        placement: intent?.targetPosition === 'before' ? 'start' : 'end',
      };
    }

    const choice = await showFlatDropGroupChooser(resolution, '');
    if (choice === FLAT_DROP_CANCEL) {
      return { cancelled: true, sectionId: '', unassign: false, placement: 'end' };
    }
    if (choice === FLAT_DROP_UNGROUPED) {
      return { cancelled: false, sectionId: '', unassign: true, placement: 'end' };
    }
    return {
      cancelled: false,
      sectionId: String(choice || ''),
      unassign: false,
      placement: choice === resolution.next?.sectionId ? 'start' : 'end',
    };
  }

